package org.example;
import org.example.config.ConfigManager;import org.example.dao.PurchaseDAO;import org.example.database.DatabaseManager;import org.example.model.*;import java.sql.*;import java.time.LocalDate;import java.util.List;
public final class PurchasePersistenceSmoke{
 public static void main(String[]a)throws Exception{ConfigManager.load();DatabaseManager.initialize();Party supplier;Item item;double before;try(Connection c=DatabaseManager.getConnection();Statement s=c.createStatement()){try(ResultSet r=s.executeQuery("SELECT id,party_code,name FROM party_master WHERE party_type='SUPPLIER' ORDER BY id LIMIT 1")){if(!r.next())throw new IllegalStateException("Smoke test requires one supplier");supplier=new Party();supplier.setId(r.getInt(1));supplier.setPartyCode(r.getString(2));supplier.setName(r.getString(3));}try(ResultSet r=s.executeQuery("SELECT item_code,description,COALESCE(opening_stock,0),COALESCE(purchase_price,1),COALESCE(gst,0) FROM item_master ORDER BY id LIMIT 1")){if(!r.next())throw new IllegalStateException("Smoke test requires one item");item=new Item();item.setItemCode(r.getString(1));item.setDescription(r.getString(2));before=r.getDouble(3);item.setPurchasePrice(r.getDouble(4));item.setGst(r.getDouble(5));}}
 double rate=item.getPurchasePrice()<=0?1:item.getPurchasePrice();PurchaseLine l=new PurchaseLine();l.setItemCode(item.getItemCode());l.setItemDescription(item.getDescription());l.setQuantity(1);l.setRate(rate);l.setGstPercent(item.getGst());l.setNetAmount(rate);l.setGstAmount(rate*item.getGst()/100);l.setTotalAmount(l.getNetAmount()+l.getGstAmount());Purchase p=new Purchase();p.setInvoiceNo("PSMOKE-"+System.currentTimeMillis());p.setInvoiceDate(LocalDate.now());p.setSupplier(supplier);p.setSubtotal(l.getNetAmount());p.setGstAmount(l.getGstAmount());p.setTotalAmount(l.getTotalAmount());p.setRemarks("Automated purchase smoke test");p.setLines(List.of(l));PurchaseDAO d=new PurchaseDAO();d.save(p);Purchase loaded=d.getByInvoice(p.getInvoiceNo());if(loaded==null||loaded.getLines()==null||loaded.getLines().size()!=1)throw new IllegalStateException("Saved purchase could not be read back");try(Connection c=DatabaseManager.getConnection();PreparedStatement q=c.prepareStatement("SELECT opening_stock FROM item_master WHERE item_code=?")){q.setString(1,item.getItemCode());try(ResultSet r=q.executeQuery()){if(!r.next()||Math.abs(r.getDouble(1)-(before+1))>.0001)throw new IllegalStateException("Stock was not increased correctly");}}System.out.println("PURCHASE_SMOKE_OK invoice="+p.getInvoiceNo()+" stock="+before+"->"+(before+1));}
}
